function replace(s,ctx){return s.replace(/{{([\s\S]*?)}}/g,(_,e)=>{const v=expression(e,ctx);return v==null?'':typeof v==='object'?JSON.stringify(v):String(v);});}
function children(source,target,ctx){let condition=null;for(const node of source.childNodes){if(node.nodeType===3){target.append(document.createTextNode(replace(node.textContent,ctx)));continue;}if(node.nodeType!==1)continue;
 const loop=node.getAttribute('data-wx-for');if(loop){const values=expression(loop.replace(/^{{|}}$/g,''),ctx)||[];Array.from(values).forEach((item,index)=>{const clone=node.cloneNode(true);clone.removeAttribute('data-wx-for');const wrap=document.createElement('div');wrap.append(clone);children(wrap,target,{...ctx,[node.getAttribute('data-wx-for-item')||'item']:item,[node.getAttribute('data-wx-for-index')||'index']:index});});continue;}
 const ifx=node.getAttribute('data-wx-if');if(ifx!==null){condition=!!expression(ifx.replace(/^{{|}}$/g,''),ctx);if(!condition)continue;}else if(node.hasAttribute('data-wx-else')){if(condition!==false)continue;condition=null;}else condition=null;
 const el=document.createElement(node.tagName.toLowerCase());for(const attr of node.attributes){if(attr.name.startsWith('bind')||attr.name.startsWith('catch')||attr.name.startsWith('data-wx-')||attr.name==='animation'||attr.name==='src'||attr.name==='data-source-src')continue;const value=replace(attr.value,ctx).replace(/(-?\d+(?:\.\d+)?)rpx/g,(_,n)=>Number(n)/2+'px');if(['disabled','checked','selected'].includes(attr.name)&&(!value||value==='false'))continue;el.setAttribute(attr.name,value);}
 if(el.tagName==='IMG'){const src=replace(node.getAttribute('data-source-src')||node.getAttribute('src')||'',ctx);const allowed=/^\/static\/tabBar\/[a-zA-Z]+\.png$/.test(src);if(allowed){el.src=src.slice(1);el.alt=src.includes('human')?'原仓库人体示意图':'原小程序导航图标';el.addEventListener('error',()=>missing(el,src));}else{missing(el,src);target.append(el);continue;}}
 children(node,el,ctx);target.append(el);
 }}
function missing(el,src){el.removeAttribute('src');el.alt='原图待补';el.dataset.missingSource=src;el.classList.add('missing-image');}
