 if(page==='book') {document.querySelector('.card-subtitle').textContent='沈先生三餐合成预设';const tab=document.querySelector('#tabbar');tab.innerHTML='<div class="custom-tabbar show"><div class="tabbar-container"><div class="tabbar-bg"></div><div class="tabbar-content">'+[['shop','商店'],['selectrise','营养册'],['AI','AI助手'],['note','空间'],['profile','个人主页']].map(([img,text],i)=>`<button class="tabbar-item ${i===2?'core-item':''} ${i===1?'active':''}" data-tab="${text}"><span class="${i===2?'core-item-wrapper':'tabbar-icon'}"><img src="static/tabBar/${img}.png" class="${i===2?'core-icon':'icon-image'}" alt=""></span><span class="tabbar-text">${text}</span></button>`).join('')+'</div></div></div>';document.querySelectorAll('.recipe-calories').forEach(e=>e.textContent='原版静态示例 · 非实测');document.querySelector('.example-desc').textContent='点击查看沈先生预设餐食结果';document.querySelector('.intake-title').textContent='营养摄入记录（合成演示）';document.querySelector('#body-card .title-text').textContent='人体影响图（离线示意，未评估）';document.querySelector('#recipe-card .card-subtitle').textContent='预设食谱示例 · 非大模型推荐';document.querySelector('#recognition-card .card-subtitle').textContent='点击展示合成餐食预设，不拍照、不上传';document.querySelectorAll('.food-img.placeholder').forEach(e=>e.textContent='原图待补');}
