 if(['showOrganDetail','showRegionDetail','goOrganImpactDetail'].includes(action)){let key=el.dataset.organ||el.dataset.key;try{key=key||JSON.parse(el.dataset.region).key;}catch{}const aliases={gut:'intestine',kidneys:'kidney'};key=aliases[key]||key;if(!ORGANS.some(x=>x[0]===key)){status('此身体部位尚未提供原版详情，未进行评估。');return;}location.href='body.html?key='+encodeURIComponent(key)+'&from='+page;return;}
