 const toggles={toggleFamilyDrawer:['familyDrawerOpen',true],closeFamilyDrawer:['familyDrawerOpen',false],openAddFoodModal:['addFoodModalOpen',true],closeAddFoodModal:['addFoodModalOpen',false],closeDeleteConfirm:['deleteConfirmOpen',false]};if(toggles[action]){const [key,value]=toggles[action];if(value)dialogReturn=focusIdentity(el);data[key]=value;render();return;}
 if(action==='toggleMetric'){data.expandedMetric=data.expandedMetric===Number(el.dataset.idx)?null:Number(el.dataset.idx);render();return;}
 if(action==='toggleFold'&&['nutritionFolded','notesFolded','impactFolded'].includes(el.dataset.type)){data[el.dataset.type]=!data[el.dataset.type];render();return;}
 if(action==='resetPhoto'){data.previewImage='';data.showResult=false;render();return;}
 if(action==='clearImage'){data.form.img='';render();return;}
