 if(action==='noop'||action==='preventBubble')return;
 if(el.dataset.tab){const routes={'营养册':'../nutrition-booklet.html','商店':'shop.html','AI助手':'aiAgent.html','空间':'digitalHuman.html','个人主页':'profile.html'};if(routes[el.dataset.tab])location.href=routes[el.dataset.tab];return;}
 if(action==='goBack'){if(page==='body'&&typeof bodyReturnURL==='function'){const target=bodyReturnURL();if(target){location.href=target;return;}}if(safeBack()){history.back();return;}const origin=params.get('from');location.href=['book','intake','recipes','record'].includes(origin)?origin+'.html':page==='detail'?'recipes.html':'book.html';return;}
 if(action==='navigateToRecipePage'){location.href='recipes.html';return;}
 if(action==='goToRecipeDetail'||action==='goToFoodDetail'){let r;try{r=JSON.parse(el.dataset.recipe||el.dataset.food);}catch{return;}location.href='detail.html?id='+encodeURIComponent(r.id);return;}
