 if(page==='record'){document.querySelectorAll('.unit').forEach(el=>el.textContent='合成预设');document.querySelectorAll('.form input,.form textarea').forEach(el=>{el.readOnly=true;el.placeholder='点击下方按钮保存一条当前页合成预设';el.setAttribute('aria-label','合成演示字段');});}
 if(page==='body'){document.querySelectorAll('.organ-tab').forEach(el=>{el.setAttribute('aria-pressed',String(el.dataset.key===data.regionKey));});document.querySelector('.organ-subtitle').textContent='沈先生合成预设';document.querySelector('.score-label').textContent='合成记录';document.querySelector('.ai-subtitle').textContent='本机预设 · 非大模型';document.querySelectorAll('canvas').forEach(el=>el.hidden=true);note(document.querySelector('.trend-card'),'近7天合成体重：'+NutriPresetDemo.snapshot().metrics.filter(m=>m.metric==='weight').map(m=>m.value).join(' → ')+' kg（编写示例，非测量）');}
 if(page==='recognition'){const tip=document.querySelector('.empty-tip');if(tip){tip.querySelector('.t1').textContent='沈先生预设餐食识别演示';tip.querySelector('.t2').textContent='点击查看预设结果，不调用相机、不上传、不进行图像识别';}document.querySelectorAll('[data-tap="takePhoto"]').forEach(el=>{el.disabled=false;el.textContent='查看预设餐食结果';});if(!data.showResult)note(document.querySelector('.result-scroll'),'已备好沈先生三餐合成样例，点击上方按钮查看。');}
 if(page==='book'){document.querySelector('.body-legend').textContent='未评估 · 不表示健康状态或风险';document.querySelectorAll('.organ-label').forEach(el=>{const organ=ORGANS.find(x=>x[0]===el.dataset.organ);if(organ){const texts=el.querySelectorAll('span');if(texts[0])texts[0].textContent=organ[1];if(texts[1])texts[1].textContent='未评估';}});document.querySelectorAll('.body-silhouette,.body-image').forEach(el=>{const figure=document.createElement('figure');figure.className='original-body-figure';const img=document.createElement('img');img.src='images/body-guide-original.svg';img.alt='原创全身人体位置示意：简化的头部、胸腹器官与四肢；请选择下方中文部位查看页面';img.width=360;img.height=520;const caption=document.createElement('figcaption');caption.textContent='人体位置示意，不代表检查结果';figure.append(img,caption);el.replaceWith(figure);});const card=document.querySelector('#body-card');if(card){const list=document.createElement('div');list.className='accessible-organs';list.setAttribute('aria-label','查看器官详情');ORGANS.forEach(([key,name])=>{const a=document.createElement('a');a.href='body.html?key='+key;a.textContent=name+' · 未评估';list.append(a);});card.append(list);}}
