function safeBack(){try{const previous=new URL(document.referrer);const here=new URL(location.href);if(history.length<=1||previous.origin!==here.origin)return false;const exactParent=new URL('../nutrition-booklet.html',here);const exactParentDirectory=new URL('../',here);if(previous.pathname===exactParent.pathname||previous.pathname===exactParentDirectory.pathname)return true;return previous.pathname.slice(0,previous.pathname.lastIndexOf('/'))===here.pathname.slice(0,here.pathname.lastIndexOf('/'))&&/\/(book|recipes|detail|intake|record|body|recognition)\.html$/.test(previous.pathname);}catch{return false;}}
function activeDialog(){return document.querySelector('.category-detail-modal.show .modal-content,.add-food-modal,.family-drawer.open');}
function focusIdentity(el){if(!el?.dataset||(!el.dataset.tap&&!el.dataset.tab))return null;const attrs={...el.dataset};const matches=Array.from(document.querySelectorAll('[data-tap],[data-tab]')).filter(item=>Object.entries(attrs).every(([key,value])=>item.dataset[key]===value));return {attrs,ordinal:matches.indexOf(el)};}
function restoreFocus(token){if(!token)return;const matches=Array.from(document.querySelectorAll('[data-tap],[data-tab]')).filter(item=>Object.entries(token.attrs).every(([key,value])=>item.dataset[key]===value));const target=matches[token.ordinal]||matches[0];if(target)target.focus({preventScroll:true});}
function manageDialog(focusToken){const dialog=activeDialog();if(dialog){dialog.setAttribute('role','dialog');dialog.setAttribute('aria-modal','true');dialog.setAttribute('aria-label',data.showCategoryModal?'全部分类':data.familyDrawerOpen?'家庭账户':'添加食物');dialog.tabIndex=-1;const close=dialog.querySelector('[data-tap="hideCategoryModal"],[data-tap="closeAddFoodModal"],[data-tap="closeFamilyDrawer"]');if(close){close.tabIndex=0;close.focus();}else dialog.focus();}else{restoreFocus(dialogReturn||focusToken);dialogReturn=null;}}
document.addEventListener('keydown',event=>{const dialog=activeDialog();if(event.key!=='Tab'||!dialog)return;const focusable=Array.from(dialog.querySelectorAll('button,a[href],input,[tabindex="0"]')).filter(el=>!el.disabled);if(!focusable.length){event.preventDefault();dialog.focus();return;}const first=focusable[0],last=focusable[focusable.length-1];if(event.shiftKey&&(document.activeElement===first||document.activeElement===dialog)){event.preventDefault();last.focus();}else if(!event.shiftKey&&(document.activeElement===last||!dialog.contains(document.activeElement))){event.preventDefault();first.focus();}});

app.addEventListener('keydown',event=>{if(page!=='book'||event.key!=='Enter'||!event.target.matches('.search-input'))return;const query=event.target.value.trim();if(!query){status('请输入模块名称，如营养、人体或食谱。');return;}const match=data.cardList.find(item=>item.name.includes(query)||query.includes(item.name));const target=match&&document.querySelector(match.id);if(!target){status('没有找到模块，请搜索营养、人体、菜品、食谱或小贴士。');return;}target.scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});target.tabIndex=-1;target.focus({preventScroll:true});status('已定位到'+match.name+'模块');});

function presetAction(action,el){
 const key=data.regionKey||'self';
 if(action==='generateAIPlan'){data.organ.aiPlan=NutriPresetDemo.plan(key);render();status('已生成本机预设方案 · 非大模型');return true;}
 if(action==='refreshMetrics'){render();status('已刷新沈先生7天合成预设，未读取真实健康数据');return true;}
 if(['saveRecord','submitManual','onPickFood','pickMealType','addSnackCard'].includes(action)){const item=NutriPresetDemo.record(key);if(data.organ)data.organ.achievements=['已记录本次演示状态',...data.organ.achievements.filter(x=>x!=='已记录本次演示状态')];data.addPromptVisible=false;data.mealPickerVisible=false;render();status('已保存当前页合成记录 '+item.id+'；刷新页面会清除，不写入账户');return true;}
 if(action==='exportData'){const blob=new Blob([NutriPresetDemo.exportData()],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='shen-preset-demo-20261022.json';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);status('已导出合成演示 JSON，不含真实账户数据');return true;}
 if(['takePhoto','chooseImage'].includes(action)){const meals=NutriPresetDemo.snapshot().meals.filter(m=>m.date==='2026-10-22');Object.assign(data,{showResult:true,recognizing:false,showWheel:false,summary:'沈先生三餐预设结果 · 并非图像识别',mealItems:meals.map(m=>({name:m.name,portion:'编写的合成份量示例',calories:m.kcal})),nutritionText:'合成餐食账面示例，仅用于体验流程。',notesText:'未拍照、未上传、未调用识别服务。',impactText:'不判断器官健康或食物治疗效果。',nutritionFolded:false,notesFolded:false,addPromptVisible:true});render();status('已载入三餐合成样例，无相机或上传');return true;}
 if(['applyAdvice','applySuggestion','compareStandard','showFoodDetail'].includes(action)){if(data.organ)data.organ.aiPlan=NutriPresetDemo.plan(key);render();status('已展示本机预设饮食记录建议；不是医学标准或处方');return true;}
 if(action==='shareOrgan'){status('可使用导出数据按钮保存本机合成演示；不会分享真实账户');return true;}
 return false;
}
